import React, { useState, useEffect, useMemo } from 'react';
import { INITIAL_PRAISE_LIST } from './constants';
import { ServiceRecord, SongStats, ServiceDraft } from './types';
import ServiceForm from './components/ServiceForm';
import HistoryList from './components/HistoryList';
import RankingList from './components/RankingList';
import BackupRestore from './components/BackupRestore';
import UnplayedList from './components/UnplayedList';
import WorkerStats from './components/WorkerStats';
import WorkerRanking from './components/WorkerRanking';
import { initDB, saveData, loadData } from './db';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'new' | 'history' | 'workers' | 'suggestions' | 'praise-ranking' | 'unplayed' | 'settings'>('new');
  const [history, setHistory] = useState<ServiceRecord[]>([]);
  const [customSongs, setCustomSongs] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [editingId, setEditingId] = useState<string | null>(null);

  const getTodayDate = () => {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  };

  const emptyRoles = { gate: '', praise: '', word: '', scripture: '' };

  const [draft, setDraft] = useState<ServiceDraft>({
    date: getTodayDate(),
    description: '',
    songs: [],
    roles: { ...emptyRoles }
  });

  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    const setup = async () => {
      try {
        await initDB();
        const data = await loadData();
        if (data) {
          if (data.history) setHistory(data.history);
          if (data.customSongs) setCustomSongs(data.customSongs);
          if (data.draft) setDraft({ ...data.draft, date: getTodayDate(), roles: data.draft.roles || { ...emptyRoles } });
        }
      } catch (e) {
        console.error("Erro no DB", e);
      } finally {
        setIsLoading(false);
      }
    };
    setup();
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    if (!isLoading) saveData({ history, customSongs, draft });
  }, [history, customSongs, draft, isLoading]);

  const fullSongList = useMemo(() => {
    return [...new Set([...INITIAL_PRAISE_LIST, ...customSongs])].sort((a, b) => a.localeCompare(b));
  }, [customSongs]);

  const songStats = useMemo(() => {
    const stats: Record<string, SongStats> = {};
    history.forEach(record => {
      record.songs.forEach(song => {
        if (!stats[song]) stats[song] = { song, count: 0, lastDate: null, history: [] };
        stats[song].count++;
        stats[song].history.push(record.date);
      });
    });
    Object.keys(stats).forEach(s => {
      stats[s].history.sort((a, b) => b.localeCompare(a));
      stats[s].lastDate = stats[s].history[0];
    });
    return stats;
  }, [history]);

  const saveRecord = (data: Omit<ServiceRecord, 'id'>) => {
    if (editingId) {
      setHistory(prev => prev.map(r => r.id === editingId ? { ...data, id: editingId } : r));
      setEditingId(null);
    } else {
      setHistory(prev => [{ ...data, id: crypto.randomUUID() }, ...prev]);
    }
    setDraft({ date: getTodayDate(), description: '', songs: [], roles: { ...emptyRoles } });
  };

  const menuItems = [
    { id: 'new', icon: 'add_circle', label: 'Novo' },
    { id: 'history', icon: 'history', label: 'Histórico' },
    { id: 'workers', icon: 'military_tech', label: 'Obreiros' },
    { id: 'suggestions', icon: 'auto_awesome', label: 'Escala' },
    { id: 'praise-ranking', icon: 'trending_up', label: 'Hinos' },
    { id: 'unplayed', icon: 'assignment_late', label: 'Restantes' },
    { id: 'settings', icon: 'tune', label: 'Sistema' },
  ] as const;

  const handleTabChange = (id: typeof activeTab) => {
    setActiveTab(id);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  if (isLoading) return (
    <div className="min-h-screen bg-[#0f172a] flex flex-col items-center justify-center text-white p-10">
      <div className="relative">
        <div className="w-24 h-24 border-4 border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin"></div>
        <img src="https://cdn-icons-png.flaticon.com/512/1672/1672225.png" className="w-12 h-12 absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" alt="Loading" />
      </div>
      <p className="mt-8 font-black tracking-widest text-[10px] uppercase animate-pulse">Iniciando Santo Antônio II...</p>
    </div>
  );

  return (
    <div className="min-h-screen flex flex-col pb-[120px] md:pb-0 md:pl-24">
      {/* SIDEBAR DESKTOP */}
      <aside className="hidden md:flex w-24 bg-[#0f172a] flex-col fixed left-0 top-0 h-screen z-[150] items-center py-10 shadow-2xl">
        <div className="mb-12">
          <img src="https://cdn-icons-png.flaticon.com/512/1672/1672225.png" className="w-10 h-10" alt="Logo" />
        </div>
        <nav className="flex-1 flex flex-col gap-8">
          {menuItems.map(item => (
            <button 
              key={item.id}
              onClick={() => handleTabChange(item.id)}
              className={`group relative flex items-center justify-center w-14 h-14 rounded-2xl transition-all duration-300 ${activeTab === item.id ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-900/40' : 'text-slate-500 hover:text-white hover:bg-white/5'}`}
            >
              <span className="material-icons text-2xl">{item.icon}</span>
              <span className="absolute left-20 bg-slate-800 text-white text-[10px] px-3 py-1.5 rounded-lg font-black opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none whitespace-nowrap uppercase tracking-widest">
                {item.label}
              </span>
            </button>
          ))}
        </nav>
      </aside>

      {/* TOP HEADER MOBILE */}
      <header className="md:hidden bg-[#0f172a] text-white p-6 sticky top-0 z-[200] flex flex-col items-center shadow-2xl border-b border-white/5">
        <div className="flex items-center gap-3">
           <img src="https://cdn-icons-png.flaticon.com/512/1672/1672225.png" className="w-8 h-8" alt="Logo" />
           <div className="flex flex-col">
              <span className="text-[9px] font-black text-indigo-400 uppercase tracking-widest">Gestão de Culto</span>
              <h1 className="text-sm font-black uppercase tracking-tight">Santo Antônio II</h1>
           </div>
        </div>
      </header>

      {/* BOTTOM NAV MOBILE */}
      <nav className="md:hidden fixed bottom-0 left-0 right-0 glass-panel border-t border-slate-200 z-[300] flex justify-around items-center px-4 pt-3 pb-[calc(1.5rem+var(--safe-area-inset-bottom))] shadow-[0_-10px_30px_rgba(0,0,0,0.05)]">
        {menuItems.slice(0, 5).map(item => (
          <button 
            key={item.id}
            onClick={() => handleTabChange(item.id)}
            className={`flex flex-col items-center gap-1 transition-all duration-300 relative ${activeTab === item.id ? 'bottom-nav-active' : 'text-slate-400'}`}
          >
            <span className="material-icons text-[26px]">{item.icon}</span>
            <span className="text-[9px] font-black uppercase tracking-tighter">{item.label}</span>
            {activeTab === item.id && <div className="nav-indicator"></div>}
          </button>
        ))}
        {/* Settings button separate or visible only if many items */}
        <button 
          onClick={() => handleTabChange('settings')}
          className={`flex flex-col items-center gap-1 transition-all duration-300 relative ${activeTab === 'settings' ? 'bottom-nav-active' : 'text-slate-400'}`}
        >
          <span className="material-icons text-[26px]">more_horiz</span>
          <span className="text-[9px] font-black uppercase tracking-tighter">Mais</span>
          {activeTab === 'settings' && <div className="nav-indicator"></div>}
        </button>
      </nav>

      {/* MAIN CONTENT AREA */}
      <main className="flex-1 w-full max-w-4xl mx-auto px-4 py-8 md:py-20">
        {isOffline && (
          <div className="mb-6 bg-amber-500/10 text-amber-600 text-[10px] font-black uppercase py-3 px-6 rounded-2xl border border-amber-500/20 text-center animate-slideUp">
            Modo Offline Ativo • Dados salvos no dispositivo
          </div>
        )}

        <div className="animate-slideUp">
          {activeTab === 'new' && <ServiceForm onSave={saveRecord} songStats={songStats} fullSongList={fullSongList} onRegisterNewSong={s => setCustomSongs(prev => [...prev, s])} draft={draft} setDraft={setDraft} editingId={editingId} onCancelEdit={() => setEditingId(null)} totalRecords={history.length} />}
          {activeTab === 'history' && <HistoryList history={history} onDelete={id => setHistory(prev => prev.filter(r => r.id !== id))} onEdit={r => { setEditingId(r.id); setDraft({ ...r }); setActiveTab('new'); }} onClearAll={() => {}} />}
          {activeTab === 'workers' && <WorkerRanking history={history} />}
          {activeTab === 'suggestions' && <WorkerStats history={history} />}
          {activeTab === 'praise-ranking' && <RankingList songStats={songStats} />}
          {activeTab === 'unplayed' && <UnplayedList fullSongList={fullSongList} history={history} />}
          {activeTab === 'settings' && <BackupRestore history={history} customSongs={customSongs} onRestore={(h, c) => { setHistory(h); setCustomSongs(c); }} />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { ServiceRecord, SongStats, ServiceDraft } from '../types';
import { WORKERS_LIST } from '../constants';

const Label = ({ children }: { children?: React.ReactNode }) => (
  <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] block mb-2 px-1">{children}</label>
);

const FormCard = ({ children, title, icon }: { children: React.ReactNode, title?: string, icon?: string }) => (
  <div className="bg-white rounded-[2.5rem] p-8 shadow-sm border border-slate-100 mb-6">
    {title && (
        <div className="flex items-center gap-3 mb-6 border-b border-slate-50 pb-4">
            <span className="material-icons text-indigo-500 text-xl">{icon}</span>
            <h3 className="text-xs font-black uppercase tracking-widest text-slate-800">{title}</h3>
        </div>
    )}
    {children}
  </div>
);

const InputWrapper = ({ children, active = false }: { children: React.ReactNode, active?: boolean }) => (
  <div className={`relative flex items-center bg-slate-50 rounded-2xl px-5 py-4 border-2 transition-all ${active ? 'border-indigo-500 bg-white shadow-lg shadow-indigo-500/5' : 'border-transparent'}`}>
    {children}
  </div>
);

interface Props {
  onSave: (record: Omit<ServiceRecord, 'id'>) => void;
  songStats: Record<string, SongStats>;
  fullSongList: string[];
  onRegisterNewSong: (song: string) => void;
  draft: ServiceDraft;
  setDraft: React.Dispatch<React.SetStateAction<ServiceDraft>>;
  editingId: string | null;
  onCancelEdit: () => void;
  totalRecords?: number;
}

const ServiceForm: React.FC<Props> = ({ onSave, songStats, fullSongList, onRegisterNewSong, draft, setDraft, editingId, onCancelEdit }) => {
  const [inputValue, setInputValue] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [pendingSong, setPendingSong] = useState<{name: string, diff: number, lastDate: string} | null>(null);
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);
  const [showSuccessBox, setShowSuccessBox] = useState(false);
  const [isInputFocused, setIsInputFocused] = useState(false);

  const dayOfWeekNames = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];
  const fullDayNames = ['DOMINGO', 'SEGUNDA-FEIRA', 'TERÇA-FEIRA', 'QUARTA-FEIRA', 'QUINTA-FEIRA', 'SEXTA-FEIRA', 'SÁBADO'];

  const dateInfo = useMemo(() => {
    const d = new Date(draft.date + 'T12:00:00');
    const dayIndex = d.getDay();
    return { name: dayOfWeekNames[dayIndex], fullName: fullDayNames[dayIndex], isSunday: dayIndex === 0, isMonday: dayIndex === 1, isWednesday: dayIndex === 3 };
  }, [draft.date]);

  useEffect(() => {
    if (!dateInfo.isSunday && !editingId) setDraft(prev => ({ ...prev, description: dateInfo.fullName }));
    else if (dateInfo.isSunday && !editingId && !['EBD', 'DOM'].includes(draft.description)) setDraft(prev => ({ ...prev, description: 'DOM' }));
  }, [dateInfo, editingId]);

  const updateRole = (role: keyof typeof draft.roles, name: string) => {
    setDraft(prev => ({ ...prev, roles: { ...prev.roles, [role]: name } }));
  };

  const handleSave = () => {
    onSave(draft);
    setShowSuccessBox(true);
  };

  const checkAndAddSong = (songName: string) => {
    const name = songName.trim();
    if (!name) return;
    if (!fullSongList.includes(name)) onRegisterNewSong(name);

    const stats = songStats[name];
    if (stats && stats.lastDate) {
      const lastDate = new Date(stats.lastDate + 'T12:00:00');
      const today = new Date(); today.setHours(12, 0, 0, 0);
      const diffDays = Math.ceil(Math.abs(today.getTime() - lastDate.getTime()) / (1000 * 60 * 60 * 24));

      if (diffDays <= 30) { 
        setPendingSong({ name, diff: diffDays, lastDate: stats.lastDate }); 
        return; 
      }
    }
    executeAdd(name);
  };

  const executeAdd = (name: string) => {
    setDraft(prev => ({ ...prev, songs: [...prev.songs, name] }));
    setInputValue('');
    setShowSuggestions(false);
    setPendingSong(null);
  };

  const suggestions = useMemo(() => {
    if (inputValue.length < 2) return [];
    const lowerInput = inputValue.toLowerCase();
    return fullSongList
      .filter(s => s.toLowerCase().includes(lowerInput))
      .slice(0, 30);
  }, [inputValue, fullSongList]);

  return (
    <div className="pb-10 space-y-6">
      <div className="flex justify-between items-center mb-4 px-2">
         <h2 className="text-2xl font-black tracking-tight text-slate-800">
            {editingId ? 'Editar Relatório' : 'Novo Relatório'}
         </h2>
         <span className="bg-indigo-50 text-indigo-600 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border border-indigo-100">
            {dateInfo.fullName}
         </span>
      </div>

      <FormCard icon="event" title="Informações do Culto">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div>
            <Label>Data</Label>
            <InputWrapper>
              <input 
                type="date" 
                value={draft.date} 
                onChange={(e) => setDraft(prev => ({ ...prev, date: e.target.value }))} 
                className="w-full bg-transparent font-bold text-slate-800" 
              />
            </InputWrapper>
          </div>
          {dateInfo.isSunday && (
            <div>
              <Label>Período</Label>
              <div className="flex bg-slate-50 p-1.5 rounded-2xl border-2 border-transparent">
                <button onClick={() => setDraft(prev => ({ ...prev, description: 'EBD' }))} className={`flex-1 py-3 text-[10px] font-black rounded-xl transition-all ${draft.description === 'EBD' ? 'bg-[#0f172a] text-white shadow-lg' : 'text-slate-400'}`}>EBD</button>
                <button onClick={() => setDraft(prev => ({ ...prev, description: 'DOM' }))} className={`flex-1 py-3 text-[10px] font-black rounded-xl transition-all ${draft.description === 'DOM' ? 'bg-[#0f172a] text-white shadow-lg' : 'text-slate-400'}`}>CULTO</button>
              </div>
            </div>
          )}
        </div>
      </FormCard>

      <FormCard icon="queue_music" title="Louvores">
        <div className="relative mb-6">
          <InputWrapper active={isInputFocused}>
            <span className="material-icons text-slate-400 mr-3">search</span>
            <input 
              type="text" 
              value={inputValue} 
              onFocus={() => setIsInputFocused(true)}
              onBlur={() => setTimeout(() => setIsInputFocused(false), 200)}
              onChange={e => {setInputValue(e.target.value); setShowSuggestions(true);}} 
              className="flex-1 bg-transparent font-bold text-slate-800 placeholder:text-slate-300" 
              placeholder="Digite o número ou nome do hino..." 
            />
            {inputValue && (
                <button onClick={() => checkAndAddSong(inputValue)} className="ml-2 w-10 h-10 bg-indigo-600 text-white rounded-xl flex items-center justify-center active:scale-95 transition-transform"><span className="material-icons">add</span></button>
            )}
          </InputWrapper>

          {showSuggestions && suggestions.length > 0 && (
            <div className="absolute z-[400] w-full mt-2 dark-glass rounded-[2rem] border border-white/10 shadow-2xl max-h-72 overflow-y-auto animate-scaleIn">
              {suggestions.map(s => (
                <button key={s} onClick={() => checkAndAddSong(s)} className="w-full p-5 text-left text-white/80 hover:bg-white/10 border-b border-white/5 last:border-0 flex justify-between items-center group">
                  <span className="font-bold text-xs truncate mr-4">{s}</span>
                  <span className="material-icons text-indigo-400 opacity-0 group-hover:opacity-100 transition-opacity">add_circle</span>
                </button>
              ))}
            </div>
          )}
        </div>

        <div className="space-y-3">
          {draft.songs.length === 0 ? (
            <div className="py-12 border-2 border-dashed border-slate-100 rounded-[2rem] flex flex-col items-center justify-center text-slate-300">
               <span className="material-icons text-4xl mb-2">music_off</span>
               <span className="text-[10px] font-black uppercase tracking-widest">Nenhum hino selecionado</span>
            </div>
          ) : (
            draft.songs.map((s, i) => (
              <div 
                key={`${s}-${i}`}
                className="flex items-center gap-4 p-4 bg-slate-50 rounded-2xl border border-transparent hover:border-indigo-100 hover:bg-white transition-all group"
              >
                <div className="w-8 h-8 bg-indigo-100 text-indigo-600 rounded-lg flex items-center justify-center text-[10px] font-black shrink-0">#{i+1}</div>
                <span className="flex-1 font-bold text-slate-700 text-xs truncate">{s}</span>
                <button onClick={() => setDraft(prev => ({...prev, songs: prev.songs.filter((_, idx) => idx !== i)}))} className="text-slate-300 hover:text-rose-500 transition-colors">
                  <span className="material-icons text-xl">remove_circle_outline</span>
                </button>
              </div>
            ))
          )}
        </div>
      </FormCard>

      <FormCard icon="assignment_ind" title="Obreiros na Escala">
        <div className="space-y-6">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
            <div>
              <Label>Portão</Label>
              <InputWrapper>
                <select value={draft.roles.gate} onChange={e => updateRole('gate', e.target.value)} className="w-full bg-transparent font-bold text-slate-800 appearance-none">
                  <option value="">Selecione...</option>
                  {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                </select>
                <span className="material-icons absolute right-5 text-slate-300 pointer-events-none">expand_more</span>
              </InputWrapper>
            </div>

            {dateInfo.isWednesday ? (
              <div className="col-span-1 sm:col-span-2 bg-indigo-50 p-6 rounded-3xl border border-indigo-100 flex items-center gap-4 text-indigo-700">
                <span className="text-3xl">🌸</span>
                <span className="text-[10px] font-black uppercase tracking-widest leading-tight">Culto dirigido pelo Grupo de Senhoras</span>
              </div>
            ) : (
              <>
                <div>
                  <Label>Louvor</Label>
                  <InputWrapper>
                    <select value={draft.roles.praise} onChange={e => updateRole('praise', e.target.value)} className="w-full bg-transparent font-bold text-slate-800 appearance-none">
                      <option value="">Selecione...</option>
                      {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                    </select>
                    <span className="material-icons absolute right-5 text-slate-300 pointer-events-none">expand_more</span>
                  </InputWrapper>
                </div>

                {!dateInfo.isMonday && (
                  <div>
                    <Label>Palavra</Label>
                    <InputWrapper>
                      <select value={draft.roles.word} onChange={e => updateRole('word', e.target.value)} className="w-full bg-transparent font-bold text-slate-800 appearance-none">
                        <option value="">Selecione...</option>
                        {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                      </select>
                      <span className="material-icons absolute right-5 text-slate-300 pointer-events-none">expand_more</span>
                    </InputWrapper>
                  </div>
                )}

                {draft.roles.word === 'TRANSMISSÃO' ? (
                  <div className="col-span-1 sm:col-span-2 bg-amber-50 p-6 rounded-3xl border border-amber-100 flex items-center gap-4 text-amber-700">
                    <span className="text-3xl">📡</span>
                    <span className="text-[10px] font-black uppercase tracking-widest leading-tight">Culto transmitido via satélite</span>
                  </div>
                ) : (
                  <div className="col-span-1 sm:col-span-2">
                    <Label>Texto Bíblico</Label>
                    <InputWrapper>
                      <input type="text" value={draft.roles.scripture} onChange={e => updateRole('scripture', e.target.value)} placeholder="Ex: João 3:16" className="w-full bg-transparent font-bold text-slate-800" />
                    </InputWrapper>
                  </div>
                )}
              </>
            )}
          </div>
        </div>
      </FormCard>

      <div className="px-2 space-y-3">
        <button 
          onClick={handleSave} 
          disabled={draft.songs.length === 0} 
          className={`w-full py-6 rounded-[2rem] font-black text-xs tracking-[0.2em] uppercase transition-all active:scale-95 flex items-center justify-center gap-3 shadow-xl ${draft.songs.length > 0 ? 'bg-indigo-600 text-white shadow-indigo-500/30' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}
        >
          <span className="material-icons text-xl">{editingId ? 'update' : 'check_circle'}</span>
          {editingId ? 'Salvar Alterações' : 'Finalizar Relatório'}
        </button>

        {editingId && (
          <button 
            onClick={onCancelEdit}
            className="w-full py-4 text-slate-400 font-black uppercase text-[10px] tracking-widest hover:text-rose-500 transition-colors"
          >
            Descartar Edição
          </button>
        )}
      </div>

      {/* SUCCESS DIALOG */}
      {showSuccessBox && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-[#0f172a]/80 backdrop-blur-md" onClick={() => setShowSuccessBox(false)}></div>
          <div className="relative bg-white rounded-[3rem] p-12 text-center max-w-sm w-full shadow-2xl animate-scaleIn">
            <div className="w-24 h-24 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mx-auto mb-8">
              <span className="material-icons text-5xl">verified</span>
            </div>
            <h3 className="text-2xl font-black text-slate-800 mb-2 uppercase tracking-tighter">Sucesso!</h3>
            <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mb-10">O relatório foi armazenado.</p>
            <button onClick={() => setShowSuccessBox(false)} className="w-full py-6 bg-[#0f172a] text-white rounded-[2rem] font-black text-xs uppercase tracking-widest active:scale-95 shadow-xl">Continuar</button>
          </div>
        </div>
      )}

      {/* PENDING SONG DIALOG */}
      {pendingSong && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-[#0f172a]/80 backdrop-blur-md"></div>
