            />
        </div>

        <div className="flex gap-3">
            <button onClick={() => setShowShareModal(true)} className="flex-1 flex items-center justify-center gap-2 py-4 bg-indigo-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl shadow-indigo-500/20 active:scale-95 transition-transform">
                <span className="material-icons text-lg">auto_stories</span>
                Relatório Mensal
            </button>
        </div>
      </div>

      <div className="space-y-12">
        {Object.keys(groupedHistory).length === 0 ? (
          <div className="py-20 text-center flex flex-col items-center">
            <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center text-slate-200 mb-4">
