            </div>
            <p className="text-slate-400 font-black uppercase text-[10px] tracking-widest">Nada encontrado</p>
          </div>
        ) : (
          (Object.entries(groupedHistory) as [string, ServiceRecord[]][]).map(([month, records]) => (
            <div key={month} className="space-y-6">
