                    {month}
                 </div>
                 <div className="flex-1 h-px bg-slate-200"></div>
              </div>

              <div className="grid gap-6 px-2">
                {records.map(r => {
                  const dateObj = new Date(r.date + 'T12:00:00');
                  const dayCode = dayOfWeekNamesShort[dateObj.getDay()];
                  const isLadiesDay = dateObj.getDay() === 3;
                  const isSatellite = r.roles.word === 'TRANSMISSÃO';

                  return (
                    <div key={r.id} className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden hover:shadow-xl transition-all group">
                      <div className="p-8">
