          <div className="absolute inset-0 bg-[#0f172a]/80 backdrop-blur-md" onClick={() => setShowShareModal(false)}></div>
          <div className="relative bg-white rounded-[3rem] p-10 max-w-sm w-full shadow-2xl animate-scaleIn">
